-- Generated by prepare_session.py. Run in a new, empty REAPER project.
local data = __SESSION_DATA__

local function available(path)
  local file = io.open(path, "rb")
  if file then file:close(); return true end
  return false
end

if reaper.CountTracks(0) ~= 0 or reaper.CountMediaItems(0) ~= 0 then
  reaper.MB("Open a new empty REAPER project before running this import.", "Film audio import", 0)
  return
end
if available(data.project_path) then
  reaper.MB("The target .RPP already exists. Create a new session instead of overwriting it.", "Film audio import", 0)
  return
end
if not available(data.video_path) then
  reaper.MB("Picture file is missing: " .. data.video_path, "Film audio import", 0)
  return
end
if data.production_path and not available(data.production_path) then
  reaper.MB("Production audio is missing: " .. data.production_path, "Film audio import", 0)
  return
end
for _, cue in ipairs(data.cues) do
  if not available(cue.path) then
    reaper.MB("Cue file is missing: " .. cue.path, "Film audio import", 0)
    return
  end
end

local function new_track(name)
  local idx = reaper.CountTracks(0)
  reaper.InsertTrackInProject(0, idx, 0)
  local track = reaper.GetTrack(0, idx)
  if not track then error("Could not create track " .. name) end
  reaper.GetSetMediaTrackInfo_String(track, "P_NAME", name, true)
  return track
end

local function add_item(track, path, name, start_at, length, source_in, gain_db, fade_in, fade_out)
  local source = reaper.PCM_Source_CreateFromFile(path)
  if not source then error("REAPER could not read " .. path) end
  local item = reaper.AddMediaItemToTrack(track)
  local take = reaper.AddTakeToMediaItem(item)
  if not take or not reaper.SetMediaItemTake_Source(take, source) then
    error("Could not place " .. name)
  end
  reaper.SetMediaItemPosition(item, start_at, false)
  reaper.SetMediaItemLength(item, length, false)
  reaper.SetMediaItemTakeInfo_Value(take, "D_STARTOFFS", source_in)
  reaper.SetMediaItemInfo_Value(item, "D_VOL", gain_db and 10 ^ (gain_db / 20) or 0)
  reaper.SetMediaItemInfo_Value(item, "D_FADEINLEN", fade_in)
  reaper.SetMediaItemInfo_Value(item, "D_FADEOUTLEN", fade_out)
  reaper.GetSetMediaItemTakeInfo_String(take, "P_NAME", name, true)
  return item
end

reaper.Undo_BeginBlock2(0)
reaper.PreventUIRefresh(1)
local ok, err = pcall(function()
  reaper.GetSetProjectInfo(0, "PROJECT_SRATE", 48000, true)
  reaper.GetSetProjectInfo(0, "PROJECT_SRATE_USE", 1, true)
  reaper.GetSetProjectInfo(0, "RENDER_BOUNDSFLAG", 0, true)
  reaper.GetSetProjectInfo(0, "RENDER_STARTPOS", 0, true)
  reaper.GetSetProjectInfo(0, "RENDER_ENDPOS", data.duration, true)
  reaper.GetSetProjectInfo(0, "RENDER_SRATE", 48000, true)
  reaper.GetSetProjectInfo(0, "RENDER_CHANNELS", 2, true)
  reaper.GetSetProjectInfo(0, "RENDER_SETTINGS", 0, true)

  local picture = new_track("00_PICTURE_REFERENCE_AUDIO_OFF")
  add_item(picture, data.video_path, "LOCKED_PICTURE", 0, data.duration, 0, nil, 0, 0)

  if data.production_path then
    local production = new_track("01_PRODUCTION_DIALOGUE_LOCATION")
    add_item(production, data.production_path, "PRODUCTION_AUDIO", 0, data.duration, 0,
      data.production_gain_db, 0, 0)
  end

  local groups = {
    {name = "MUSIC", number = "02"},
    {name = "FOLEY", number = "03"},
    {name = "AMBIENCE", number = "04"},
    {name = "SFX", number = "05"},
    {name = "OTHER", number = "06"}
  }
  for _, group in ipairs(groups) do
    local children = {}
    for _, cue in ipairs(data.cues) do
      if cue.category == group.name then children[#children + 1] = cue end
    end
    if #children > 0 then
      local bus = new_track(group.number .. "_" .. group.name .. "_BUS")
      reaper.SetMediaTrackInfo_Value(bus, "I_FOLDERDEPTH", 1)
      for idx, cue in ipairs(children) do
        local track = new_track(cue.id .. "_" .. cue.name)
        add_item(track, cue.path, cue.id .. "_" .. cue.name, cue.start, cue.duration,
          cue.source_in, cue.gain_db, cue.fade_in, cue.fade_out)
        if idx == #children then
          reaper.SetMediaTrackInfo_Value(track, "I_FOLDERDEPTH", -1)
        end
      end
    end
  end
  reaper.AddProjectMarker2(0, true, 0, data.duration, "FULL_FILM", -1, 0)
  reaper.UpdateArrange()
  reaper.Main_SaveProjectEx(0, data.project_path, 0)
end)
reaper.PreventUIRefresh(-1)
reaper.Undo_EndBlock2(0, "Import locked film audio package", -1)
if not ok then
  reaper.MB("Import failed: " .. tostring(err) .. "\nThe project was not saved. Open a new project before retrying.", "Film audio import", 0)
  return
end
reaper.MB("Imported " .. tostring(#data.cues) .. " cues and saved the REAPER project. Verify picture and audio sync before mixing.", "Film audio import", 0)
